interface UserRepository {
    suspend fun load(id: String): User?
}

// Fake — a real implementation with a control surface
class FakeUserRepository(private var users: List<User> = emptyList()) : UserRepository {
    override suspend fun load(id: String): User? = users.find { it.id == id }
    fun seed(list: List<User>) { users = list }
}

// Mock (MockK) — stubs + records the interaction
val repo = mockk<UserRepository>()
every { repo.load("1") } returns user(1)
verify(exactly = 1) { repo.load("1") }

// The rot: a refactor from load(id) to load(ids) breaks every verify
// for no behavioural reason — the fake only needed its seed updated.

class FinalGreeter { fun greet() = "hi" }   // final — classic Mockito can't subclass it

val greeter = mockk<FinalGreeter>()
every { greeter.greet() } returns "bye"            // MockK: no open needed

// suspend functions need coEvery / coVerify, not every/verify
val repo = mockk<UserRepository>()
coEvery { repo.load("1") } returns user(1)
coVerify(exactly = 1) { repo.load("1") }

// the seam that beats both: a fake that reproduces behaviour
class FakeUserRepository : UserRepository {
    private val users = MutableStateFlow(emptyList<User>())
    override fun observe() = users
    override suspend fun load(id: String): User? = users.value.find { it.id == id }
}

class FeedViewModel(
    private val repo: FeedRepository,
    private val dispatcher: CoroutineDispatcher = Dispatchers.IO,
) : ViewModel() {
    private val _state = MutableStateFlow<UiState>(UiState.Loading)
    val state = _state.asStateFlow()

    init {
        viewModelScope.launch(dispatcher) {
            repo.observe().collect { _state.value = it }
        }
    }
}

@OptIn(ExperimentalCoroutinesApi::class)
class FeedViewModelTest {
    @get:Rule val mainRule = MainDispatcherRule()   // setMain(StandardTestDispatcher())

    @Test
    fun `shows content once the repo emits`() = runTest {
        val vm = FeedViewModel(FakeRepo(items), StandardTestDispatcher(testScheduler))
        advanceUntilIdle()
        assertEquals(UiState.Content(items), vm.state.value)
    }
}

@OptIn(ExperimentalCoroutinesApi::class)
class FeedFlowTest {

    @Test
    fun `turbine asserts items then completion`() = runTest {
        flowOf(item(1), item(2)).test {
            assertEquals(item(1), awaitItem())
            assertEquals(item(2), awaitItem())
            awaitComplete()          // also fails if events were unconsumed
        }
    }

    @Test
    fun `plain collector records everything`() = runTest {
        val seen = mutableListOf<Item>()
        backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) {
            flowOf(item(1), item(2)).toList(seen)
        }
        advanceUntilIdle()
        assertEquals(listOf(item(1), item(2)), seen)
    }
}

class DetailViewModel(
    private val savedState: SavedStateHandle,
    private val repo: DetailRepository,
) : ViewModel() {
    val id: String = checkNotNull(savedState["itemId"])          // restored before init
    val item: StateFlow<Item?> = repo.observe(id)
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), null)
}

@OptIn(ExperimentalCoroutinesApi::class)
class DetailViewModelTest {
    @get:Rule val mainRule = MainDispatcherRule()

    @Test
    fun `restores the id from the saved-state bundle`() = runTest {
        val savedState = SavedStateHandle(mapOf("itemId" to "42"))   // the bundle that WAS saved
        val vm = DetailViewModel(savedState, FakeRepo(items))
        advanceUntilIdle()
        assertEquals(items["42"], vm.item.value)
    }

    @Test
    fun `a write re-emits on the flow-backed key`() = runTest {
        val savedState = SavedStateHandle(mapOf("itemId" to "42"))
        val flow = savedState.getStateFlow<String?>("itemId", null)
        savedState["itemId"] = "99"
        assertEquals("99", flow.value)
    }
}
